public enum Colour {

    /** dark-coloured pieces
     */
    BLACK,

    /** light-coloured pieces
     */
    WHITE;

    /**
     * Returns the other colour.
     *
     * @return the other colour.
     */
    public Colour otherColour() {
        switch (this) {
            case WHITE:
                return BLACK;
            case BLACK:
                return WHITE;
            default:
                throw new IllegalStateException("Invalid colour");
        }
    }
}

public Colour otherColour() {
    switch (this) {
        case WHITE:
            return BLACK;
        case BLACK:
            return WHITE;
        default:
            throw new IllegalStateException("Invalid colour");
    }
}

