    for (int rank = 0; rank < NUMBER_OF_RANKS; ++rank) {
        for (int file = 0; file < NUMBER_OF_FILES; ++file) {
            Piece piece = getPiece(rank, file);
            if (piece != null && piece.is(KING)
                    && piece.is(colour)) {
                return new Square(rank, file);
            }
        }
    }
    return null;
}

