public class StandardMaterialEvaluation implements Evaluation {

    @Override
    public int evaluatePosition(Position position, Colour pointOfView) {
        int total = 0;

        for (int rank = 0; rank < 8; ++rank) {
            for (int file = 0; file < 8; ++file) {
                Piece piece = position.getPiece(rank, file);
                if (piece != null) {
                    int value = pieceValue(piece);
                    if (piece.getColour() == pointOfView) {
                        total += value;
                    } else {
                        total -= value;
                    }
                }
            }
        }

        return total;
    }

    /**
     * Material value of the given piece.
     */
    protected int pieceValue(final Piece piece) {
        switch (piece.getType()) {
            case PAWN:
                return 1;
            case KNIGHT:
            case BISHOP:
                return 3;
            case ROOK:
                return 5;
            case QUEEN:
                return 9;
            default:
                return 0;
        }
    }
}

@Override
public int evaluatePosition(Position position, Colour pointOfView) {
    int total = 0;

    for (int rank = 0; rank < 8; ++rank) {
        for (int file = 0; file < 8; ++file) {
            Piece piece = position.getPiece(rank, file);
            if (piece != null) {
                int value = pieceValue(piece);
                if (piece.getColour() == pointOfView) {
                    total += value;
                } else {
                    total -= value;
                }
            }
        }
    }

    return total;
}

protected int pieceValue(final Piece piece) {
    switch (piece.getType()) {
        case PAWN:
            return 1;
        case KNIGHT:
        case BISHOP:
            return 3;
        case ROOK:
            return 5;
        case QUEEN:
            return 9;
        default:
            return 0;
    }
}

