        this.key = new byte[8];
        System.arraycopy(data, 0, this.key, 0, 8);

        this.move = new byte[2];
        System.arraycopy(data, 8, this.move, 0, 2);

        this.weight = new byte[2];
        System.arraycopy(data, 10, this.weight, 0, 2);
    }

    String getMove() {
        return getMoveFrom() + getMoveTo();
    }

