}

static byte[] longToByteArray(long source) {
    byte[] bytesKey = new byte[8];
    String sBytes = Long.toBinaryString(source);
    while (sBytes.length() < 64) {
        sBytes = "0" + sBytes;
    }
    for (int i = 0; i < 8; i++) {
