    addReachableSquaresInDirection(position, from, 0, -1, squares);
    addReachableSquaresInDirection(position, from, -1, 0, squares);

    // Diagonal (bishop directions)
    addReachableSquaresInDirection(position, from, 1, 1, squares);
    addReachableSquaresInDirection(position, from, 1, -1, squares);
    addReachableSquaresInDirection(position, from, -1, 1, squares);
